/// <summary>
///    Enables or disables action pane buttons according to active record data.
/// </summary>
protected void setButtonEnabled()
{
    next setButtonEnabled();

    this.listPage().actionPaneControlEnabled(formcontrolstr(ReturnTableListPage, METApplyDispositionCode),
        returnTableButtonStateProvider.parmApplyDispositionCodeEnabled());
}
